def _refresh_handle(self) -> None:
    """
    Make sure the handle reads the current version of the database file.

    Writes replace the file, so the handle has to be re-opened when another
    storage instance has written to the file (our handle would keep
    reading the old version otherwise) or when re-opening it after a write
    has failed.
    """
    if not self._handle.closed:
        try:
            current = os.stat(self._path)
        except OSError:
            # The file has been removed, so keep reading what we've got
            return

        if os.path.samestat(os.fstat(self._handle.fileno()), current):
            return

    handle = self._open_for_reading()
    self._handle.close()
    self._handle = handle

def _open_for_reading(self) -> IO[Any]:
    return open(self._path, mode=self._read_mode, encoding=self._encoding)

def _remove_temp_files(self) -> None:
    """
    Remove temporary files left behind by interrupted writes.
    """
    # Only match names ``write`` uses for this file. Their random part
    # never contains dots, which rules out temporary files of other
    # databases whose names start with this one's (like ``db.json.v2``).
    temp_file = re.compile(
        re.escape(self._temp_prefix) + r'[^.]+' +
        re.escape(self._TEMP_SUFFIX)
    )
    directory = os.path.dirname(self._path)

    try:
        names = os.listdir(directory)
    except OSError:
        return

    for name in names:
        if temp_file.fullmatch(name):
            try:
                os.remove(os.path.join(directory, name))
            except OSError:
                pass
